        CollectionAssert.AreEquivalent(new[] { "a@example.com", "c@example.com" }, updated.Members.Select(m => m.UserEmail).ToArray());
        Assert.IsTrue(updated.Members.Any(m => m.Id == a.Id));
        Assert.IsFalse(updated.Members.Any(m => m.Id == b.Id));
    }

    [TestMethod]
    public async Task OwnershipCanMoveAndAMemberCanBeReplacedByTheSameEmail()
    {
        await AddUsersAsync("a@example.com", "b@example.com");
        var team = await PostAsync<TeamDto>("/teams", NewTeam("T", Member("a@example.com", true), Member("b@example.com", false)));
        var a = team.Members.Single(m => m.UserEmail == "a@example.com");
        var b = team.Members.Single(m => m.UserEmail == "b@example.com");

        var moved = await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("T",
            new MemberInput { Id = a.Id, UserEmail = "a@example.com", IsOwner = false },
            new MemberInput { Id = b.Id, UserEmail = "b@example.com", IsOwner = true }));
        Assert.AreEqual(HttpStatusCode.OK, moved.StatusCode, await moved.Content.ReadAsStringAsync());

        // a removed and re-added in the same request
        var replaced = await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("T",
            Member("a@example.com", false),
            new MemberInput { Id = b.Id, UserEmail = "b@example.com", IsOwner = true }));
        Assert.AreEqual(HttpStatusCode.OK, replaced.StatusCode, await replaced.Content.ReadAsStringAsync());
    }

    [TestMethod]
    public async Task UnknownTeamIsNotFound()
    {
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/teams/{UnknownId}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.PutAsJsonAsync($"/teams/{UnknownId}", NewTeam("X"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.DeleteAsync($"/teams/{UnknownId}")).StatusCode);
    }

    [TestMethod]
    public async Task NameIsRequiredAndAtMost50Characters()
    {
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam("")), "Name");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam(new string('x', 51))), "Name");
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/teams", NewTeam(new string('x', 50)))).StatusCode);
    }

    [TestMethod]
    public async Task DescriptionIsAtMost200Characters()
    {
        var tooLong = NewTeam("A");
        tooLong.Description = new string('x', 201);
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", tooLong), "Description");

        var fine = NewTeam("B");
        fine.Description = new string('x', 200);
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/teams", fine)).StatusCode);
    }

    [TestMethod]
    public async Task MemberEmailIsRequiredAtMost50CharactersAndOfAnExistingUser()
    {
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam("A", Member("", true))), "Members[0].UserEmail");

        var longEmail = new string('x', 45) + "@e.com";
        await AddUsersAsync(longEmail);
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam("B", Member(longEmail, true))), "Members[0].UserEmail");

        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam("C", Member("nobody@example.com", true))), "Members[0].UserEmail");
    }

    [TestMethod]
    public async Task SameEmailCannotAppearTwiceInATeamButCanInTwoTeams()
    {
        await AddUsersAsync("a@example.com", "b@example.com");

        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams",
            NewTeam("A", Member("a@example.com", true), Member("a@example.com", false))), "Members[1].UserEmail");

        await PostAsync<TeamDto>("/teams", NewTeam("B", Member("a@example.com", true)));
        await PostAsync<TeamDto>("/teams", NewTeam("C", Member("a@example.com", true)));
    }

    [TestMethod]
    public async Task TeamWithMembersHasExactlyOneOwner()
    {
        await AddUsersAsync("a@example.com", "b@example.com");

        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams", NewTeam("None", Member("a@example.com", false))), "Members");
        await AssertInvalidAsync(await Client.PostAsJsonAsync("/teams",
            NewTeam("Two", Member("a@example.com", true), Member("b@example.com", true))), "Members");

        var team = await PostAsync<TeamDto>("/teams", NewTeam("One", Member("a@example.com", true), Member("b@example.com", false)));
        var response = await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("One", Member("a@example.com", false)));
        await AssertInvalidAsync(response, "Members");
    }

    [TestMethod]
    public async Task MemberIdOfAnotherTeamIsInvalid()
    {
        await AddUsersAsync("a@example.com");
        var other = await PostAsync<TeamDto>("/teams", NewTeam("Other", Member("a@example.com", true)));
        var team = await PostAsync<TeamDto>("/teams", NewTeam("Mine"));

        var response = await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("Mine",
            new MemberInput { Id = other.Members[0].Id, UserEmail = "a@example.com", IsOwner = true }));

        await AssertInvalidAsync(response, "Members[0].Id");
    }

    [TestMethod]
    public async Task InvalidUpdateChangesNothing()
    {
        var team = await PostAsync<TeamDto>("/teams", NewTeam("Keep"));

        await AssertInvalidAsync(await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("")), "Name");

        Assert.AreEqual("Keep", (await Client.GetFromJsonAsync<TeamDto>($"/teams/{team.Id}"))!.Name);
    }

    [TestMethod]
    public async Task NameMustBeUnique()
    {
        var first = await PostAsync<TeamDto>("/teams", NewTeam("Same"));
        var second = await PostAsync<TeamDto>("/teams", NewTeam("Other"));

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.PostAsJsonAsync("/teams", NewTeam("Same"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.PutAsJsonAsync($"/teams/{second.Id}", NewTeam("Same"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.PutAsJsonAsync($"/teams/{first.Id}", NewTeam("Same"))).StatusCode);
    }

    [TestMethod]
    public async Task TeamWithMembersCannotBeDeleted()
    {
        await AddUsersAsync("a@example.com");
        var team = await PostAsync<TeamDto>("/teams", NewTeam("Busy", Member("a@example.com", true)));

        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);
    }

    [TestMethod]
    public async Task TeamsArePagedAndSorted()
    {
        foreach (var name in new[] { "c", "a", "b" })
        {
            await PostAsync<TeamDto>("/teams", NewTeam(name));
        }

        var page = await Client.GetFromJsonAsync<Page<TeamDto>>("/teams?orderBy=Name&descending=true&page=2&pageSize=2");

        Assert.AreEqual(3, page!.TotalCount);
        Assert.AreEqual("a", page.Items.Single().Name);
        await AssertInvalidAsync(await Client.GetAsync("/teams?orderBy=Members"), "orderBy");
        await AssertInvalidAsync(await Client.GetAsync("/teams?pageSize=0"), "pageSize");
    }

    [TestMethod]
    public async Task ReadingRequiresAnAuthenticatedCaller()
    {
        var team = await PostAsync<TeamDto>("/teams", NewTeam("Read"));

        AuthenticateAs();
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/teams")).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);

        Unauthenticate();
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync("/teams")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.GetAsync($"/teams/{team.Id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.PostAsJsonAsync("/teams", NewTeam("Anon"))).StatusCode);
    }

    [TestMethod]
    public async Task WritingRequiresTheManageTeamsRight()
    {
        var team = await PostAsync<TeamDto>("/teams", NewTeam("Guarded"));

        AuthenticateAs(UMRights.ManageUsers);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PostAsJsonAsync("/teams", NewTeam("New"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("Guarded"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);

        AuthenticateAs(UMRights.ManageTeams);
        Assert.AreEqual(HttpStatusCode.Created, (await Client.PostAsJsonAsync("/teams", NewTeam("New"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.PutAsJsonAsync($"/teams/{team.Id}", NewTeam("Guarded2"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/teams/{team.Id}")).StatusCode);
    }

    private static MemberInput Member(string email, bool isOwner) => new() { UserEmail = email, IsOwner = isOwner };

    private static TeamInput NewTeam(string name, params MemberInput[] members) => new() { Name = name, Members = [.. members] };

    private async Task AddUsersAsync(params string[] emails)
    {
        foreach (var email in emails)
        {
            await PostAsync<UserDto>("/users", new UserInput { Email = email, Provider = "local" });
        }
    }
